iv><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="指标定义标准" tabindex="-1"><a class="header-anchor" href="#指标定义标准"><span>指标定义标准</span></a></h3>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token keyword">package</span> gametelemetry</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">"go.opentelemetry.io/otel/metric"</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> GameMetrics <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// === 用户活跃指标 ===</span></span>
<span class="line">    DAU metric<span class="token punctuation">.</span>Int64ObservableGauge    <span class="token comment">// 日活跃用户</span></span>
<span class="line">    MAU metric<span class="token punctuation">.</span>Int64ObservableGauge    <span class="token comment">// 月活跃用户</span></span>
<span class="line">    NewUsers metric<span class="token punctuation">.</span>Int64Counter       <span class="token comment">// 新注册用户数</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// === 会话指标 ===</span></span>
<span class="line">    SessionDuration metric<span class="token punctuation">.</span>Float64Histogram  <span class="token comment">// 会话时长分布</span></span>
<span class="line">    SessionCount metric<span class="token punctuation">.</span>Int64Counter         <span class="token comment">// 会话数</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// === 经济指标 ===</span></span>
<span class="line">    Revenue metric<span class="token punctuation">.</span>Float64Counter            <span class="token comment">// 收入</span></span>
<span class="line">    ARPU metric<span class="token punctuation">.</span>Float64ObservableGauge       <span class="token comment">// 平均每用户收益</span></span>
<span class="line">    PaidUserCount metric<span class="token punctuation">.</span>Int64Counter        <span class="token comment">// 付费用户数</span></span>
<span class="line">    TransactionCount metric<span class="token punctuation">.</span>Int64Counter     <span class="token comment">// 交易数量</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// === 内容指标 ===</span></span>
<span class="line">    LevelCompletion metric<span class="token punctuation">.</span>Float64Histogram  <span class="token comment">// 关卡完成率分布</span></span>
<span class="line">    LevelDuration metric<span class="token punctuation">.</span>Float64Histogram    <span class="token comment">// 关卡耗时分布</span></span>
<span class="line">    QuestCompletion metric<span class="token punctuation">.</span>Int64Counter      <span class="token comment">// 任务完成数</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// === 社交指标 ===</span></span>
<span class="line">    FriendAdditions metric<span class="token punctuation">.</span>Int64Counter      <span class="token comment">// 添加好友数</span></span>
<span class="line">    ChatMessages metric<span class="token punctuation">.</span>Int64Counter         <span class="token comment">// 聊天消息数</span></span>
<span class="line">    GuildMembers metric<span class="token punctuation">.</span>Int64ObservableGauge <span class="token comment">// 公会成员数</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// === 技术指标 ===</span></span>
<span class="line">    ClientFPS metric<span class="token punctuation">.</span>Float64Histogram        <span class="token comment">// 客户端帧率</span></span>
<span class="line">    LoadTime metric<span class="token punctuation">.</span>Float64Histogram         <span class="token comment">// 加载时间</span></span>
<span class="line">    NetworkLatency metric<span class="token punctuation">.</span>Float64Histogram   <span class="token comment">// 网络延迟</span></span>
<span class="line">    CrashRate metric<span class="token punctuation">.</span>Float64ObservableGauge  <span class="token comment">// 崩溃率</span></span>
<span class="line">    APILatency metric<span class="token punctuation">.</span>Float64Histogram       <span class="token comment">// API延迟</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">NewGameMetrics</span><span class="token punctuation">(</span>meter metric<span class="token punctuation">.</span>Meter<span class="token punctuation">)</span> <span class="token operator">*</span>GameMetrics <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token operator">&amp;</span>GameMetrics<span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 用户活跃指标</span></span>
<span class="line">        DAU<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Int64ObservableGauge</span><span class="token punctuation">(</span><span class="token string">"game.users.daily_active"</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithDescription</span><span class="token punctuation">(</span><span class="token string">"Daily Active Users"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithUnit</span><span class="token punctuation">(</span><span class="token string">"{users}"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">        MAU<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Int64ObservableGauge</span><span class="token punctuation">(</span><span class="token string">"game.users.monthly_active"</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithDescription</span><span class="token punctuation">(</span><span class="token string">"Monthly Active Users"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithUnit</span><span class="token punctuation">(</span><span class="token string">"{users}"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">        NewUsers<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Int64Counter</span><span class="token punctuation">(</span><span class="token string">"game.users.new_registrations"</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithDescription</span><span class="token punctuation">(</span><span class="token string">"New user registrations"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithUnit</span><span class="token punctuation">(</span><span class="token string">"{users}"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 会话指标 (使用建议的桶配置)</span></span>
<span class="line">        SessionDuration<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Float64Histogram</span><span class="token punctuation">(</span><span class="token string">"game.session.duration"</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithDescription</span><span class="token punctuation">(</span><span class="token string">"Game session duration"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithUnit</span><span class="token punctuation">(</span><span class="token string">"s"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithExplicitBucketBoundaries</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">float64</span><span class="token punctuation">{</span></span>
<span class="line">                <span class="token number">30</span><span class="token punctuation">,</span> <span class="token number">60</span><span class="token punctuation">,</span> <span class="token number">120</span><span class="token punctuation">,</span> <span class="token number">300</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token number">1200</span><span class="token punctuation">,</span> <span class="token number">1800</span><span class="token punctuation">,</span> <span class="token number">3600</span><span class="token punctuation">,</span> <span class="token number">7200</span><span class="token punctuation">,</span>  <span class="token comment">// 30秒到2小时</span></span>
<span class="line">            <span class="token punctuation">}</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">        SessionCount<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Int64Counter</span><span class="token punctuation">(</span><span class="token string">"game.session.count"</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithDescription</span><span class="token punctuation">(</span><span class="token string">"Number of game sessions"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithUnit</span><span class="token punctuation">(</span><span class="token string">"{sessions}"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 经济指标</span></span>
<span class="line">        Revenue<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Float64Counter</span><span class="token punctuation">(</span><span class="token string">"game.economy.revenue"</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithDescription</span><span class="token punctuation">(</span><span class="token string">"Game revenue in USD"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithUnit</span><span class="token punctuation">(</span><span class="token string">"USD"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">        ARPU<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Float64ObservableGauge</span><span class="token punctuation">(</span><span class="token string">"game.economy.arpu"</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithDescription</span><span class="token punctuation">(</span><span class="token string">"Average Revenue Per User"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithUnit</span><span class="token punctuation">(</span><span class="token string">"USD"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">        PaidUserCount<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Int64Counter</span><span class="token punctuation">(</span><span class="token string">"game.economy.paid_users"</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithDescription</span><span class="token punctuation">(</span><span class="token string">"Number of paying users"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithUnit</span><span class="token punctuation">(</span><span class="token string">"{users}"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 内容指标</span></span>
<span class="line">        LevelCompletion<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Float64Histogram</span><span class="token punctuation">(</span><span class="token string">"game.content.level.completion_rate"</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithDescription</span><span class="token punctuation">(</span><span class="token string">"Level completion rate"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithUnit</span><span class="token punctuation">(</span><span class="token string">"1"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment">// 比率，无单位</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithExplicitBucketBoundaries</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">float64</span><span class="token punctuation">{</span></span>
<span class="line">                <span class="token number">0.1</span><span class="token punctuation">,</span> <span class="token number">0.2</span><span class="token punctuation">,</span> <span class="token number">0.3</span><span class="token punctuation">,</span> <span class="token number">0.4</span><span class="token punctuation">,</span> <span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">0.6</span><span class="token punctuation">,</span> <span class="token number">0.7</span><span class="token punctuation">,</span> <span class="token number">0.8</span><span class="token punctuation">,</span> <span class="token number">0.9</span><span class="token punctuation">,</span> <span class="token number">0.95</span><span class="token punctuation">,</span> <span class="token number">0.99</span><span class="token punctuation">,</span> <span class="token number">1.0</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token punctuation">}</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">        LevelDuration<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Float64Histogram</span><span class="token punctuation">(</span><span class="token string">"game.content.level.duration"</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithDescription</span><span class="token punctuation">(</span><span class="token string">"Time to complete level"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithUnit</span><span class="token punctuation">(</span><span class="token string">"s"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            metric<span class="token punctuation">.</span><span class="token function">WithExplicitBucketBoundaries</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">float64</span><span class="token punctuation">{</span></span>
<span class="line">                <span class="token number">10</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">,</span> <span class="token number">60</span><span class="token punctuation">,</span> <span class="token number">120</span><span class="token punctuation">,</span> <span class="token number">300</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token number">1200</span><span class="token punctuation">,</span> <span class="token number">1800</span><span class="token punctuation">,</span> <span class="token number">3600</span><span class="token punctuation">,</span>  <span class="token comment">// 10秒到1小时</span></span>
