ne-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="⚙️-opentelemetry-collector-配置" tabindex="-1"><a class="header-anchor" href="#⚙️-opentelemetry-collector-配置"><span>⚙️ OpenTelemetry Collector 配置</span></a></h2>
<h3 id="游戏优化的collector配置" tabindex="-1"><a class="header-anchor" href="#游戏优化的collector配置"><span>游戏优化的Collector配置</span></a></h3>
<div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre v-pre><code class="language-yaml"><span class="line"><span class="token comment"># otel-collector-game.yaml</span></span>
<span class="line"><span class="token key atrule">receivers</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token comment"># OTLP接收器 - 接收客户端和服务器数据</span></span>
<span class="line">  <span class="token key atrule">otlp</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">protocols</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">grpc</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token key atrule">endpoint</span><span class="token punctuation">:</span> 0.0.0.0<span class="token punctuation">:</span><span class="token number">4317</span></span>
<span class="line">      <span class="token key atrule">http</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token key atrule">endpoint</span><span class="token punctuation">:</span> 0.0.0.0<span class="token punctuation">:</span><span class="token number">4318</span></span>
<span class="line">        <span class="token key atrule">cors</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">allowed_origins</span><span class="token punctuation">:</span></span>
<span class="line">            <span class="token punctuation">-</span> <span class="token string">"*"</span></span>
<span class="line">          <span class="token key atrule">allowed_headers</span><span class="token punctuation">:</span></span>
<span class="line">            <span class="token punctuation">-</span> <span class="token string">"*"</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment"># 文件日志接收器 - 接收游戏服务器日志</span></span>
<span class="line">  <span class="token key atrule">filelog</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">include</span><span class="token punctuation">:</span> <span class="token punctuation">[</span> <span class="token string">"/var/log/game/*.log"</span> <span class="token punctuation">]</span></span>
<span class="line">    <span class="token key atrule">operators</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">type</span><span class="token punctuation">:</span> json_parser</span>
<span class="line">        <span class="token key atrule">parse_from</span><span class="token punctuation">:</span> body</span>
<span class="line">        <span class="token key atrule">parse_to</span><span class="token punctuation">:</span> attributes</span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">type</span><span class="token punctuation">:</span> move</span>
<span class="line">        <span class="token key atrule">from</span><span class="token punctuation">:</span> attributes.level</span>
<span class="line">        <span class="token key atrule">to</span><span class="token punctuation">:</span> severity_text</span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">type</span><span class="token punctuation">:</span> move</span>
<span class="line">        <span class="token key atrule">from</span><span class="token punctuation">:</span> attributes.msg</span>
<span class="line">        <span class="token key atrule">to</span><span class="token punctuation">:</span> body</span>
<span class="line"></span>
<span class="line"><span class="token key atrule">processors</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token comment"># 内存限制器 - 防止OOM</span></span>
<span class="line">  <span class="token key atrule">memory_limiter</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">limit_mib</span><span class="token punctuation">:</span> <span class="token number">1024</span></span>
<span class="line">    <span class="token key atrule">spike_limit_mib</span><span class="token punctuation">:</span> <span class="token number">256</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment"># 批处理器 - 优化网络和存储性能</span></span>
<span class="line">  <span class="token key atrule">batch</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">timeout</span><span class="token punctuation">:</span> 1s</span>
<span class="line">    <span class="token key atrule">send_batch_size</span><span class="token punctuation">:</span> <span class="token number">1024</span></span>
<span class="line">    <span class="token key atrule">send_batch_max_size</span><span class="token punctuation">:</span> <span class="token number">2048</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment"># 数据转换器 - 游戏业务逻辑处理</span></span>
<span class="line">  <span class="token key atrule">transform</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">trace_statements</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">context</span><span class="token punctuation">:</span> span</span>
<span class="line">        <span class="token key atrule">statements</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token comment"># 添加部署环境标签</span></span>
<span class="line">          <span class="token punctuation">-</span> set(attributes<span class="token punctuation">[</span><span class="token string">"deployment.environment"</span><span class="token punctuation">]</span><span class="token punctuation">,</span> "production")</span>
<span class="line"></span>
<span class="line">          <span class="token comment"># 用户ID脱敏处理</span></span>
<span class="line">          <span class="token punctuation">-</span> replace_pattern(attributes<span class="token punctuation">[</span><span class="token string">"user.id"</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string">"(?P&lt;prefix>.{3}).*(?P&lt;suffix>.{2})"</span><span class="token punctuation">,</span> "$$<span class="token punctuation">{</span>prefix<span class="token punctuation">}</span><span class="token important">***$$</span><span class="token punctuation">{</span>suffix<span class="token punctuation">}</span>") where attributes<span class="token punctuation">[</span><span class="token string">"user.id"</span><span class="token punctuation">]</span> <span class="token tag">!=</span> nil</span>
<span class="line"></span>
<span class="line">          <span class="token comment"># 计算会话时长</span></span>
<span class="line">          <span class="token punctuation">-</span> set(attributes<span class="token punctuation">[</span><span class="token string">"session.duration_minutes"</span><span class="token punctuation">]</span><span class="token punctuation">,</span> attributes<span class="token punctuation">[</span><span class="token string">"session.duration"</span><span class="token punctuation">]</span> / 60) where attributes<span class="token punctuation">[</span><span class="token string">"session.duration"</span><span class="token punctuation">]</span> <span class="token tag">!=</span> nil</span>
<span class="line"></span>
<span class="line">          <span class="token comment"># 添加游戏业务标签</span></span>
<span class="line">          <span class="token punctuation">-</span> set(attributes<span class="token punctuation">[</span><span class="token string">"game.category"</span><span class="token punctuation">]</span><span class="token punctuation">,</span> "rpg") where attributes<span class="token punctuation">[</span><span class="token string">"game.id"</span><span class="token punctuation">]</span> == "fantasy<span class="token punctuation">-</span>quest"</span>
<span class="line">          <span class="token punctuation">-</span> set(attributes<span class="token punctuation">[</span><span class="token string">"game.category"</span><span class="token punctuation">]</span><span class="token punctuation">,</span> "casual") where attributes<span class="token punctuation">[</span><span class="token string">"game.id"</span><span class="token punctuation">]</span> == "puzzle<span class="token punctuation">-</span>match"</span>
<span class="line"></span>
<span class="line">    <span class="token key atrule">metric_statements</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">context</span><span class="token punctuation">:</span> metric</span>
<span class="line">        <span class="token key atrule">statements</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token comment"># 转换单位：毫秒 -> 秒</span></span>
<span class="line">          <span class="token punctuation">-</span> set(unit<span class="token punctuation">,</span> "s") where name == "game.client.load_time"</span>
<span class="line">          <span class="token punctuation">-</span> set(value<span class="token punctuation">,</span> value / 1000) where name == "game.client.load_time"</span>
<span class="line"></span>
<span class="line">          <span class="token comment"># 添加性能等级标签</span></span>
<span class="line">          <span class="token punctuation">-</span> set(attributes<span class="token punctuation">[</span><span class="token string">"performance.tier"</span><span class="token punctuation">]</span><span class="token punctuation">,</span> "high") where name == "game.client.fps" and value <span class="token punctuation">></span>= 60</span>
<span class="line">          <span class="token punctuation">-</span> set(attributes<span class="token punctuation">[</span><span class="token string">"performance.tier"</span><span class="token punctuation">]</span><span class="token punctuation">,</span> "medium") where name == "game.client.fps" and value <span class="token punctuation">></span>= 30 and value &lt; 60</span>
<span class="line">          <span class="token punctuation">-</span> set(attributes<span class="token punctuation">[</span><span class="token string">"performance.tier"</span><span class="token punctuation">]</span><span class="token punctuation">,</span> "low") where name == "game.client.fps" and value &lt; 30</span>
<span class="line"></span>
<span class="line">    <span class="token key atrule">log_statements</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">context</span><span class="token punctuation">:</span> log</span>
<span class="line">        <span class="token key atrule">statements</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token comment"># 提取结构化日志字段</span></span>
<span class="line">          <span class="token punctuation">-</span> merge_maps(cache<span class="token punctuation">,</span> attributes<span class="token punctuation">,</span> "upsert") where attributes <span class="token tag">!=</span> nil</span>
<span class="line">          <span class="token punctuation">-</span> set(severity_text<span class="token punctuation">,</span> "ERROR") where attributes<span class="token punctuation">[</span><span class="token string">"level"</span><span class="token punctuation">]</span> == "error"</span>
<span class="line">          <span class="token punctuation">-</span> set(severity_text<span class="token punctuation">,</span> "WARN") where attributes<span class="token punctuation">[</span><span class="token string">"level"</span><span class="token punctuation">]</span> == "warn"</span>
<span class="line">          <span class="token punctuation">-</span> set(severity_text<span class="token punctuation">,</span> "INFO") where attributes<span class="token punctuation">[</span><span class="token string">"level"</span><span class="token punctuation">]</span> == "info"</span>
<span class="line"></span>
<span class="line">  <span class="token comment"># 资源处理器 - 添加资源标识</span></span>
<span class="line">  <span class="token key atrule">resource</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">attributes</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">key</span><span class="token punctuation">:</span> service.namespace</span>
<span class="line">        <span class="token key atrule">value</span><span class="token punctuation">:</span> <span class="token string">"gaming"</span></span>
<span class="line">        <span class="token key atrule">action</span><span class="token punctuation">:</span> upsert</span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">key</span><span class="token punctuation">:</span> service.instance.id</span>
<span class="line">        <span class="token key atrule">from_attribute</span><span class="token punctuation">:</span> host.name</span>
<span class="line">        <span class="token key atrule">action</span><span class="token punctuation">:</span> insert</span>
<span class="line"></span>
<span class="line">  <span class="token comment"># 采样器 - 智能采样策略</span></span>
<span class="line">  <span class="token key atrule">probabilistic_sampler</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">sampling_percentage</span><span class="token punctuation">:</span> <span class="token number">10</span>  <span class="token comment"># 基础采样率10%</span></span>
<span class="line">    <span class="token key atrule">hash_seed</span><span class="token punctuation">:</span> <span class="token number">22</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment"># 属性过滤器 - 移除敏感信息</span></span>
<span class="line">  <span class="token key atrule">attributes</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">actions</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">key</span><span class="token punctuation">:</span> client.ip</span>
<span class="line">        <span class="token key atrule">action</span><span class="token punctuation">:</span> delete</span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">key</span><span class="token punctuation">:</span> user.email</span>
<span class="line">        <span class="token key atrule">action</span><span class="token punctuation">:</span> delete</span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">key</span><span class="token punctuation">:</span> payment.card_number</span>
<span class="line">        <span class="token key atrule">action</span><span class="token punctuation">:</span> delete</span>
<span class="line"></span>
<span class="line"><span class="token key atrule">exporters</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token comment"># ClickHouse导出器 - 主要分析数据库</span></span>
<span class="line">  <span class="token key atrule">clickhouse</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">endpoint</span><span class="token punctuation">:</span> <span class="token string">"http://clickhouse:8123"</span></span>
<span class="line">    <span class="token key atrule">database</span><span class="token punctuation">:</span> <span class="token string">"game_analytics"</span></span>
<span class="line">    <span class="token key atrule">username</span><span class="token punctuation">:</span> <span class="token string">"analytics_user"</span></span>
<span class="line">    <span class="token key atrule">password</span><span class="token punctuation">:</span> <span class="token string">"analytics_password"</span></span>
<span class="line">    <span class="token key atrule">timeout</span><span class="token punctuation">:</span> 10s</span>
<span class="line">    <span class="token key atrule">retry_on_failure</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">enabled</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">      <span class="token key atrule">initial_interval</span><span class="token punctuation">:</span> 1s</span>
<span class="line">      <span class="token key atrule">max_interval</span><span class="token punctuation">:</span> 30s</span>
<span class="line">      <span class="token key atrule">max_elapsed_time</span><span class="token punctuation">:</span> 300s</span>
<span class="line"></span>
<span class="line">    <span class="token comment"># 表映射配置</span></span>
<span class="line">    <span class="token key atrule">traces_table_name</span><span class="token punctuation">:</span> <span class="token string">"otel_traces"</span></span>
<span class="line">    <span class="token key atrule">metrics_table_name</span><span class="token punctuation">:</span> <span class="token string">"otel_metrics"</span></span>
<span class="line">    <span class="token key atrule">logs_table_name</span><span class="token punctuation">:</span> <span class="token string">"otel_logs"</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># TTL配置</span></span>
<span class="line">    <span class="token key atrule">ttl_days</span><span class="token punctuation">:</span> <span class="token number">90</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># ClickHouse特定优化</span></span>
<span class="line">    <span class="token key atrule">create_schema</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">    <span class="token key atrule">engine</span><span class="token punctuation">:</span> <span class="token string">"MergeTree()"</span></span>
<span class="line">    <span class="token key atrule">partition_by</span><span class="token punctuation">:</span> <span class="token string">"toYYYYMM(timestamp)"</span></span>
<span class="line">    <span class="token key atrule">order_by</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">"game_id"</span><span class="token punctuation">,</span> <span class="token string">"user_id"</span><span class="token punctuation">,</span> <span class="token string">"timestamp"</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment"># Redis导出器 - 实时缓存</span></span>
<span class="line">  <span class="token key atrule">redis</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">endpoint</span><span class="token punctuation">:</span> <span class="token string">"redis:6379"</span></span>
<span class="line">    <span class="token key atrule">db</span><span class="token punctuation">:</span> <span class="token number">0</span></span>
<span class="line">    <span class="token key atrule">timeout</span><span class="token punctuation">:</span> 5s</span>
<span class="line"></span>
<span class="line">    <span class="token comment"># Key前缀配置</span></span>
<span class="line">    <span class="token key atrule">key_prefix</span><span class="token punctuation">:</span> <span class="token string">"otel:game:"</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># 过期时间配置</span></span>
<span class="line">    <span class="token key atrule">ttl</span><span class="token punctuation">:</span> <span class="token number">3600</span>  <span class="token comment"># 1小时</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># 仅导出关键实时指标</span></span>
<span class="line">    <span class="token key atrule">metrics_filter</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"game.users.daily_active"</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"game.users.online_count"</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"game.economy.revenue"</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"game.session.count"</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment"># Kafka导出器 - 流处理</span></span>
<span class="line">  <span class="token key atrule">kafka</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">brokers</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">"kafka1:9092"</span><span class="token punctuation">,</span> <span class="token string">"kafka2:9092"</span><span class="token punctuation">]</span></span>
<span class="line">    <span class="token key atrule">topic</span><span class="token punctuation">:</span> <span class="token string">"game-telemetry"</span></span>
<span class="line">    <span class="token key atrule">partition</span><span class="token punctuation">:</span> <span class="token number">0</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># 压缩配置</span></span>
<span class="line">    <span class="token key atrule">compression</span><span class="token punctuation">:</span> <span class="token string">"gzip"</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># 批量发送配置</span></span>
<span class="line">    <span class="token key atrule">max_message_bytes</span><span class="token punctuation">:</span> <span class="token number">1000000</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment"># Prometheus导出器 - 监控告警</span></span>
<span class="line">  <span class="token key atrule">prometheus</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">endpoint</span><span class="token punctuation">:</span> <span class="token string">"0.0.0.0:8889"</span></span>
<span class="line">    <span class="token key atrule">namespace</span><span class="token punctuation">:</span> <span class="token string">"game"</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># 标签配置</span></span>
<span class="line">    <span class="token key atrule">const_labels</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">environment</span><span class="token punctuation">:</span> <span class="token string">"production"</span></span>
<span class="line">      <span class="token key atrule">service</span><span class="token punctuation">:</span> <span class="token string">"game-analytics"</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># 仅导出聚合指标</span></span>
<span class="line">    <span class="token key atrule">metric_expiration</span><span class="token punctuation">:</span> 5m</span>
<span class="line"></span>
<span class="line">    <span class="token comment"># 资源到标签的映射</span></span>
<span class="line">    <span class="token key atrule">resource_to_telemetry_conversion</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">enabled</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment"># 日志文件导出器 - 调试用</span></span>
<span class="line">  <span class="token key atrule">file</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">path</span><span class="token punctuation">:</span> <span class="token string">"/var/log/otel-collector/game-telemetry.log"</span></span>
<span class="line">    <span class="token key atrule">rotation</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">max_megabytes</span><span class="token punctuation">:</span> <span class="token number">100</span></span>
<span class="line">      <span class="token key atrule">max_days</span><span class="token punctuation">:</span> <span class="token number">7</span></span>
<span class="line"></span>
<span class="line"><span class="token key atrule">service</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token comment"># 处理管道配置</span></span>
<span class="line">  <span class="token key atrule">pipelines</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token comment"># Traces管道 - 用户行为路径分析</span></span>
<span class="line">    <span class="token key atrule">traces</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">receivers</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>otlp<span class="token punctuation">]</span></span>
<span class="line">      <span class="token key atrule">processors</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>memory_limiter<span class="token punctuation">,</span> resource<span class="token punctuation">,</span> transform<span class="token punctuation">,</span> probabilistic_sampler<span class="token punctuation">,</span> attributes<span class="token punctuation">,</span> batch<span class="token punctuation">]</span></span>
<span class="line">      <span class="token key atrule">exporters</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>clickhouse<span class="token punctuation">,</span> file<span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># Metrics管道 - 游戏KPI指标</span></span>
<span class="line">    <span class="token key atrule">metrics</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">receivers</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>otlp<span class="token punctuation">]</span></span>
<span class="line">      <span class="token key atrule">processors</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>memory_limiter<span class="token punctuation">,</span> resource<span class="token punctuation">,</span> transform<span class="token punctuation">,</span> batch<span class="token punctuation">]</span></span>
<span class="line">      <span class="token key atrule">exporters</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>clickhouse<span class="token punctuation">,</span> redis<span class="token punctuation">,</span> prometheus<span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># Logs管道 - 游戏事件日志</span></span>
<span class="line">    <span class="token key atrule">logs</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">receivers</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>otlp<span class="token punctuation">,</span> filelog<span class="token punctuation">]</span></span>
<span class="line">      <span class="token key atrule">processors</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>memory_limiter<span class="token punctuation">,</span> resource<span class="token punctuation">,</span> transform<span class="token punctuation">,</span> batch<span class="token punctuation">]</span></span>
<span class="line">      <span class="token key atrule">exporters</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>clickhouse<span class="token punctuation">,</span> file<span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment"># 扩展配置</span></span>
<span class="line">  <span class="token key atrule">extensions</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>health_check<span class="token punctuation">,</span> pprof<span class="token punctuation">,</span> zpages<span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment"># 遥测配置</span></span>
<span class="line">  <span class="token key atrule">telemetry</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">logs</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">level</span><span class="token punctuation">:</span> <span class="token string">"info"</span></span>
<span class="line">    <span class="token key atrule">metrics</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">address</span><span class="token punctuation">:</span> <span class="token string">"0.0.0.0:8888"</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 健康检查配置</span></span>
<span class="line"><span class="token key atrule">health_check</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">endpoint</span><span class="token punctuation">:</span> <span class="token string">"0.0.0.0:13133"</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 性能分析配置</span></span>
<span class="line"><span class="token key atrule">pprof</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">endpoint</span><span class="token punctuation">:</span> <span class="token string">"localhost:1777"</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 调试页面配置</span></span>
<span class="line"><span class="token key atrule">zpages</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">endpoint</span><span class="token punctuation">:</span> <span class="token string">"localhost:55679"</span></span>
<span class="line"></span></code></pre>
