ine-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="📊-数据查询示例" tabindex="-1"><a class="header-anchor" href="#📊-数据查询示例"><span>📊 数据查询示例</span></a></h2>
<h3 id="clickhouse查询优化" tabindex="-1"><a class="header-anchor" href="#clickhouse查询优化"><span>ClickHouse查询优化</span></a></h3>
<div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre v-pre><code class="language-sql"><span class="line"><span class="token comment">-- 游戏核心KPI实时查询</span></span>
<span class="line"><span class="token comment">-- 查询最近24小时的DAU趋势</span></span>
<span class="line"><span class="token keyword">SELECT</span></span>
<span class="line">    toHour<span class="token punctuation">(</span><span class="token keyword">timestamp</span><span class="token punctuation">)</span> <span class="token keyword">as</span> <span class="token keyword">hour</span><span class="token punctuation">,</span></span>
<span class="line">    uniqExact<span class="token punctuation">(</span>attributes<span class="token punctuation">[</span><span class="token string">'user.id'</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">as</span> dau<span class="token punctuation">,</span></span>
<span class="line">    <span class="token function">count</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">as</span> total_events</span>
<span class="line"><span class="token keyword">FROM</span> otel_traces</span>
<span class="line"><span class="token keyword">WHERE</span></span>
<span class="line">    span_name <span class="token operator">=</span> <span class="token string">'user.login'</span></span>
<span class="line">    <span class="token operator">AND</span> <span class="token keyword">timestamp</span> <span class="token operator">>=</span> <span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> <span class="token keyword">INTERVAL</span> <span class="token number">24</span> <span class="token keyword">HOUR</span></span>
<span class="line">    <span class="token operator">AND</span> attributes<span class="token punctuation">[</span><span class="token string">'game.id'</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">'my-game'</span></span>
<span class="line"><span class="token keyword">GROUP</span> <span class="token keyword">BY</span> <span class="token keyword">hour</span></span>
<span class="line"><span class="token keyword">ORDER</span> <span class="token keyword">BY</span> <span class="token keyword">hour</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">-- 关卡完成率分析（按难度分组）</span></span>
<span class="line"><span class="token keyword">WITH</span> level_attempts <span class="token keyword">AS</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token keyword">SELECT</span></span>
<span class="line">        attributes<span class="token punctuation">[</span><span class="token string">'content.id'</span><span class="token punctuation">]</span> <span class="token keyword">as</span> level_id<span class="token punctuation">,</span></span>
<span class="line">        attributes<span class="token punctuation">[</span><span class="token string">'content.difficulty'</span><span class="token punctuation">]</span> <span class="token keyword">as</span> difficulty<span class="token punctuation">,</span></span>
<span class="line">        attributes<span class="token punctuation">[</span><span class="token string">'user.id'</span><span class="token punctuation">]</span> <span class="token keyword">as</span> user_id<span class="token punctuation">,</span></span>
<span class="line">        span_name<span class="token punctuation">,</span></span>
<span class="line">        <span class="token keyword">timestamp</span></span>
<span class="line">    <span class="token keyword">FROM</span> otel_traces</span>
<span class="line">    <span class="token keyword">WHERE</span> span_name <span class="token operator">IN</span> <span class="token punctuation">(</span><span class="token string">'gameplay.level.start'</span><span class="token punctuation">,</span> <span class="token string">'gameplay.level.complete'</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token operator">AND</span> <span class="token keyword">timestamp</span> <span class="token operator">>=</span> today<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> <span class="token keyword">INTERVAL</span> <span class="token number">7</span> <span class="token keyword">DAY</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">completion_stats <span class="token keyword">AS</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token keyword">SELECT</span></span>
<span class="line">        level_id<span class="token punctuation">,</span></span>
<span class="line">        difficulty<span class="token punctuation">,</span></span>
<span class="line">        countIf<span class="token punctuation">(</span>span_name <span class="token operator">=</span> <span class="token string">'gameplay.level.start'</span><span class="token punctuation">)</span> <span class="token keyword">as</span> attempts<span class="token punctuation">,</span></span>
<span class="line">        countIf<span class="token punctuation">(</span>span_name <span class="token operator">=</span> <span class="token string">'gameplay.level.complete'</span><span class="token punctuation">)</span> <span class="token keyword">as</span> completions</span>
<span class="line">    <span class="token keyword">FROM</span> level_attempts</span>
<span class="line">    <span class="token keyword">GROUP</span> <span class="token keyword">BY</span> level_id<span class="token punctuation">,</span> difficulty</span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">SELECT</span></span>
<span class="line">    level_id<span class="token punctuation">,</span></span>
<span class="line">    difficulty<span class="token punctuation">,</span></span>
<span class="line">    attempts<span class="token punctuation">,</span></span>
<span class="line">    completions<span class="token punctuation">,</span></span>
<span class="line">    <span class="token function">round</span><span class="token punctuation">(</span>completions <span class="token operator">*</span> <span class="token number">100.0</span> <span class="token operator">/</span> attempts<span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token keyword">as</span> completion_rate<span class="token punctuation">,</span></span>
<span class="line">    <span class="token keyword">CASE</span></span>
<span class="line">        <span class="token keyword">WHEN</span> completion_rate <span class="token operator">>=</span> <span class="token number">80</span> <span class="token keyword">THEN</span> <span class="token string">'Easy'</span></span>
<span class="line">        <span class="token keyword">WHEN</span> completion_rate <span class="token operator">>=</span> <span class="token number">60</span> <span class="token keyword">THEN</span> <span class="token string">'Normal'</span></span>
<span class="line">        <span class="token keyword">WHEN</span> completion_rate <span class="token operator">>=</span> <span class="token number">40</span> <span class="token keyword">THEN</span> <span class="token string">'Hard'</span></span>
<span class="line">        <span class="token keyword">ELSE</span> <span class="token string">'Very Hard'</span></span>
<span class="line">    <span class="token keyword">END</span> <span class="token keyword">as</span> difficulty_assessment</span>
<span class="line"><span class="token keyword">FROM</span> completion_stats</span>
<span class="line"><span class="token keyword">WHERE</span> attempts <span class="token operator">>=</span> <span class="token number">100</span>  <span class="token comment">-- 过滤样本量太小的关卡</span></span>
<span class="line"><span class="token keyword">ORDER</span> <span class="token keyword">BY</span> completion_rate <span class="token keyword">DESC</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">-- 用户行为路径分析（漏斗分析）</span></span>
<span class="line"><span class="token keyword">WITH</span> user_journey <span class="token keyword">AS</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token keyword">SELECT</span></span>
<span class="line">        attributes<span class="token punctuation">[</span><span class="token string">'user.id'</span><span class="token punctuation">]</span> <span class="token keyword">as</span> user_id<span class="token punctuation">,</span></span>
<span class="line">        span_name <span class="token keyword">as</span> event_type<span class="token punctuation">,</span></span>
<span class="line">        <span class="token keyword">timestamp</span><span class="token punctuation">,</span></span>
<span class="line">        ROW_NUMBER<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">OVER</span> <span class="token punctuation">(</span></span>
<span class="line">            <span class="token keyword">PARTITION</span> <span class="token keyword">BY</span> attributes<span class="token punctuation">[</span><span class="token string">'user.id'</span><span class="token punctuation">]</span></span>
<span class="line">            <span class="token keyword">ORDER</span> <span class="token keyword">BY</span> <span class="token keyword">timestamp</span></span>
<span class="line">        <span class="token punctuation">)</span> <span class="token keyword">as</span> event_sequence</span>
<span class="line">    <span class="token keyword">FROM</span> otel_traces</span>
<span class="line">    <span class="token keyword">WHERE</span></span>
<span class="line">        <span class="token keyword">timestamp</span> <span class="token operator">>=</span> today<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> <span class="token keyword">INTERVAL</span> <span class="token number">1</span> <span class="token keyword">DAY</span></span>
<span class="line">        <span class="token operator">AND</span> span_name <span class="token operator">IN</span> <span class="token punctuation">(</span></span>
<span class="line">            <span class="token string">'user.login'</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">'gameplay.level.start'</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">'economy.purchase.start'</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">'economy.purchase.complete'</span></span>
<span class="line">        <span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">funnel_analysis <span class="token keyword">AS</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token keyword">SELECT</span></span>
<span class="line">        user_id<span class="token punctuation">,</span></span>
<span class="line">        <span class="token function">SUM</span><span class="token punctuation">(</span><span class="token keyword">CASE</span> <span class="token keyword">WHEN</span> event_type <span class="token operator">=</span> <span class="token string">'user.login'</span> <span class="token keyword">THEN</span> <span class="token number">1</span> <span class="token keyword">ELSE</span> <span class="token number">0</span> <span class="token keyword">END</span><span class="token punctuation">)</span> <span class="token keyword">as</span> login_count<span class="token punctuation">,</span></span>
<span class="line">        <span class="token function">SUM</span><span class="token punctuation">(</span><span class="token keyword">CASE</span> <span class="token keyword">WHEN</span> event_type <span class="token operator">=</span> <span class="token string">'gameplay.level.start'</span> <span class="token keyword">THEN</span> <span class="token number">1</span> <span class="token keyword">ELSE</span> <span class="token number">0</span> <span class="token keyword">END</span><span class="token punctuation">)</span> <span class="token keyword">as</span> level_start_count<span class="token punctuation">,</span></span>
<span class="line">        <span class="token function">SUM</span><span class="token punctuation">(</span><span class="token keyword">CASE</span> <span class="token keyword">WHEN</span> event_type <span class="token operator">=</span> <span class="token string">'economy.purchase.start'</span> <span class="token keyword">THEN</span> <span class="token number">1</span> <span class="token keyword">ELSE</span> <span class="token number">0</span> <span class="token keyword">END</span><span class="token punctuation">)</span> <span class="token keyword">as</span> purchase_start_count<span class="token punctuation">,</span></span>
<span class="line">        <span class="token function">SUM</span><span class="token punctuation">(</span><span class="token keyword">CASE</span> <span class="token keyword">WHEN</span> event_type <span class="token operator">=</span> <span class="token string">'economy.purchase.complete'</span> <span class="token keyword">THEN</span> <span class="token number">1</span> <span class="token keyword">ELSE</span> <span class="token number">0</span> <span class="token keyword">END</span><span class="token punctuation">)</span> <span class="token keyword">as</span> purchase_complete_count</span>
<span class="line">    <span class="token keyword">FROM</span> user_journey</span>
<span class="line">    <span class="token keyword">GROUP</span> <span class="token keyword">BY</span> user_id</span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">SELECT</span></span>
<span class="line">    <span class="token function">count</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">as</span> total_users<span class="token punctuation">,</span></span>
<span class="line">    countIf<span class="token punctuation">(</span>login_count <span class="token operator">></span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">as</span> logged_in_users<span class="token punctuation">,</span></span>
<span class="line">    countIf<span class="token punctuation">(</span>level_start_count <span class="token operator">></span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">as</span> played_users<span class="token punctuation">,</span></span>
<span class="line">    countIf<span class="token punctuation">(</span>purchase_start_count <span class="token operator">></span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">as</span> purchase_attempt_users<span class="token punctuation">,</span></span>
<span class="line">    countIf<span class="token punctuation">(</span>purchase_complete_count <span class="token operator">></span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">as</span> paying_users<span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">-- 转化率计算</span></span>
<span class="line">    <span class="token function">round</span><span class="token punctuation">(</span>played_users <span class="token operator">*</span> <span class="token number">100.0</span> <span class="token operator">/</span> logged_in_users<span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token keyword">as</span> login_to_play_rate<span class="token punctuation">,</span></span>
<span class="line">    <span class="token function">round</span><span class="token punctuation">(</span>purchase_attempt_users <span class="token operator">*</span> <span class="token number">100.0</span> <span class="token operator">/</span> played_users<span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token keyword">as</span> play_to_purchase_attempt_rate<span class="token punctuation">,</span></span>
<span class="line">    <span class="token function">round</span><span class="token punctuation">(</span>paying_users <span class="token operator">*</span> <span class="token number">100.0</span> <span class="token operator">/</span> purchase_attempt_users<span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token keyword">as</span> purchase_success_rate</span>
<span class="line"><span class="token keyword">FROM</span> funnel_analysis<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">-- 收入分析（按产品和支付方式）</span></span>
<span class="line"><span class="token keyword">SELECT</span></span>
<span class="line">    attributes<span class="token punctuation">[</span><span class="token string">'economy.product_id'</span><span class="token punctuation">]</span> <span class="token keyword">as</span> product_id<span class="token punctuation">,</span></span>
<span class="line">    attributes<span class="token punctuation">[</span><span class="token string">'economy.payment_method'</span><span class="token punctuation">]</span> <span class="token keyword">as</span> payment_method<span class="token punctuation">,</span></span>
<span class="line">    <span class="token function">count</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">as</span> transaction_count<span class="token punctuation">,</span></span>
<span class="line">    <span class="token function">sum</span><span class="token punctuation">(</span>attributes<span class="token punctuation">[</span><span class="token string">'purchase.amount'</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">as</span> total_revenue<span class="token punctuation">,</span></span>
<span class="line">    <span class="token function">avg</span><span class="token punctuation">(</span>attributes<span class="token punctuation">[</span><span class="token string">'purchase.amount'</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">as</span> avg_transaction_value<span class="token punctuation">,</span></span>
<span class="line">    uniqExact<span class="token punctuation">(</span>attributes<span class="token punctuation">[</span><span class="token string">'user.id'</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">as</span> unique_buyers</span>
<span class="line"><span class="token keyword">FROM</span> otel_traces</span>
<span class="line"><span class="token keyword">WHERE</span></span>
<span class="line">    span_name <span class="token operator">=</span> <span class="token string">'economy.purchase.complete'</span></span>
<span class="line">    <span class="token operator">AND</span> <span class="token keyword">timestamp</span> <span class="token operator">>=</span> today<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> <span class="token keyword">INTERVAL</span> <span class="token number">7</span> <span class="token keyword">DAY</span></span>
<span class="line">    <span class="token operator">AND</span> attributes<span class="token punctuation">[</span><span class="token string">'payment.status'</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">'success'</span></span>
<span class="line"><span class="token keyword">GROUP</span> <span class="token keyword">BY</span> product_id<span class="token punctuation">,</span> payment_method</span>
<span class="line"><span class="token keyword">ORDER</span> <span class="token keyword">BY</span> total_revenue <span class="token keyword">DESC</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">-- 性能问题分析（低FPS用户分析）</span></span>
<span class="line"><span class="token keyword">SELECT</span></span>
<span class="line">    attributes<span class="token punctuation">[</span><span class="token string">'client.platform'</span><span class="token punctuation">]</span> <span class="token keyword">as</span> platform<span class="token punctuation">,</span></span>
<span class="line">    attributes<span class="token punctuation">[</span><span class="token string">'device.model'</span><span class="token punctuation">]</span> <span class="token keyword">as</span> device_model<span class="token punctuation">,</span></span>
<span class="line">    attributes<span class="token punctuation">[</span><span class="token string">'performance.tier'</span><span class="token punctuation">]</span> <span class="token keyword">as</span> performance_tier<span class="token punctuation">,</span></span>
<span class="line">    <span class="token function">count</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">as</span> sample_count<span class="token punctuation">,</span></span>
<span class="line">    <span class="token function">avg</span><span class="token punctuation">(</span><span class="token keyword">value</span><span class="token punctuation">)</span> <span class="token keyword">as</span> avg_fps<span class="token punctuation">,</span></span>
<span class="line">    quantile<span class="token punctuation">(</span><span class="token number">0.5</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token keyword">value</span><span class="token punctuation">)</span> <span class="token keyword">as</span> median_fps<span class="token punctuation">,</span></span>
<span class="line">    quantile<span class="token punctuation">(</span><span class="token number">0.95</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token keyword">value</span><span class="token punctuation">)</span> <span class="token keyword">as</span> p95_fps<span class="token punctuation">,</span></span>
<span class="line">    countIf<span class="token punctuation">(</span><span class="token keyword">value</span> <span class="token operator">&lt;</span> <span class="token number">30</span><span class="token punctuation">)</span> <span class="token keyword">as</span> low_fps_count</span>
<span class="line"><span class="token keyword">FROM</span> otel_metrics</span>
<span class="line"><span class="token keyword">WHERE</span></span>
<span class="line">    metric_name <span class="token operator">=</span> <span class="token string">'game.client.fps'</span></span>
<span class="line">    <span class="token operator">AND</span> <span class="token keyword">timestamp</span> <span class="token operator">>=</span> <span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> <span class="token keyword">INTERVAL</span> <span class="token number">24</span> <span class="token keyword">HOUR</span></span>
<span class="line"><span class="token keyword">GROUP</span> <span class="token keyword">BY</span> platform<span class="token punctuation">,</span> device_model<span class="token punctuation">,</span> performance_tier</span>
<span class="line"><span class="token keyword">HAVING</span> sample_count <span class="token operator">>=</span> <span class="token number">10</span></span>
<span class="line"><span class="token keyword">ORDER</span> <span class="token keyword">BY</span> avg_fps <span class="token keyword">ASC</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre>
