iv><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="🚀-部署指南" tabindex="-1"><a class="header-anchor" href="#🚀-部署指南"><span>🚀 部署指南</span></a></h2>
<h3 id="docker-compose-部署" tabindex="-1"><a class="header-anchor" href="#docker-compose-部署"><span>Docker Compose 部署</span></a></h3>
<div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre v-pre><code class="language-yaml"><span class="line"><span class="token comment"># docker-compose-otel-game.yml</span></span>
<span class="line"><span class="token key atrule">version</span><span class="token punctuation">:</span> <span class="token string">'3.8'</span></span>
<span class="line"></span>
<span class="line"><span class="token key atrule">services</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token comment"># OpenTelemetry Collector</span></span>
<span class="line">  <span class="token key atrule">otel-collector</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> otel/opentelemetry<span class="token punctuation">-</span>collector<span class="token punctuation">:</span>0.88.0</span>
<span class="line">    <span class="token key atrule">container_name</span><span class="token punctuation">:</span> game<span class="token punctuation">-</span>otel<span class="token punctuation">-</span>collector</span>
<span class="line">    <span class="token key atrule">ports</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"4317:4317"</span>   <span class="token comment"># OTLP gRPC receiver</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"4318:4318"</span>   <span class="token comment"># OTLP HTTP receiver</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"8889:8889"</span>   <span class="token comment"># Prometheus exporter</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"13133:13133"</span> <span class="token comment"># Health check</span></span>
<span class="line">    <span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> ./otel<span class="token punctuation">-</span>collector<span class="token punctuation">-</span>game.yaml<span class="token punctuation">:</span>/etc/otel<span class="token punctuation">-</span>collector<span class="token punctuation">-</span>config.yaml</span>
<span class="line">      <span class="token punctuation">-</span> ./logs<span class="token punctuation">:</span>/var/log/game</span>
<span class="line">    <span class="token key atrule">command</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">"--config=/etc/otel-collector-config.yaml"</span><span class="token punctuation">]</span></span>
<span class="line">    <span class="token key atrule">depends_on</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> clickhouse</span>
<span class="line">      <span class="token punctuation">-</span> redis</span>
<span class="line">    <span class="token key atrule">environment</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> GOMEMLIMIT=1024MiB</span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line">  <span class="token comment"># ClickHouse - 时序数据仓库</span></span>
<span class="line">  <span class="token key atrule">clickhouse</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> clickhouse/clickhouse<span class="token punctuation">-</span>server<span class="token punctuation">:</span><span class="token number">23.8</span></span>
<span class="line">    <span class="token key atrule">container_name</span><span class="token punctuation">:</span> game<span class="token punctuation">-</span>clickhouse</span>
<span class="line">    <span class="token key atrule">ports</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"8123:8123"</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"9000:9000"</span></span>
<span class="line">    <span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> clickhouse_data<span class="token punctuation">:</span>/var/lib/clickhouse</span>
<span class="line">      <span class="token punctuation">-</span> ./clickhouse/config.xml<span class="token punctuation">:</span>/etc/clickhouse<span class="token punctuation">-</span>server/config.xml</span>
<span class="line">      <span class="token punctuation">-</span> ./clickhouse/users.xml<span class="token punctuation">:</span>/etc/clickhouse<span class="token punctuation">-</span>server/users.xml</span>
<span class="line">    <span class="token key atrule">environment</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> CLICKHOUSE_DB=game_analytics</span>
<span class="line">      <span class="token punctuation">-</span> CLICKHOUSE_USER=analytics_user</span>
<span class="line">      <span class="token punctuation">-</span> CLICKHOUSE_PASSWORD=analytics_password</span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line">  <span class="token comment"># Redis - 实时缓存</span></span>
<span class="line">  <span class="token key atrule">redis</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> redis<span class="token punctuation">:</span>7.2<span class="token punctuation">-</span>alpine</span>
<span class="line">    <span class="token key atrule">container_name</span><span class="token punctuation">:</span> game<span class="token punctuation">-</span>redis</span>
<span class="line">    <span class="token key atrule">ports</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"6379:6379"</span></span>
<span class="line">    <span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> redis_data<span class="token punctuation">:</span>/data</span>
<span class="line">    <span class="token key atrule">command</span><span class="token punctuation">:</span> redis<span class="token punctuation">-</span>server <span class="token punctuation">-</span><span class="token punctuation">-</span>appendonly yes <span class="token punctuation">-</span><span class="token punctuation">-</span>maxmemory 512mb <span class="token punctuation">-</span><span class="token punctuation">-</span>maxmemory<span class="token punctuation">-</span>policy allkeys<span class="token punctuation">-</span>lru</span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line">  <span class="token comment"># Kafka - 流处理（可选）</span></span>
<span class="line">  <span class="token key atrule">kafka</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> confluentinc/cp<span class="token punctuation">-</span>kafka<span class="token punctuation">:</span>7.4.0</span>
<span class="line">    <span class="token key atrule">container_name</span><span class="token punctuation">:</span> game<span class="token punctuation">-</span>kafka</span>
<span class="line">    <span class="token key atrule">ports</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"9092:9092"</span></span>
<span class="line">    <span class="token key atrule">environment</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">KAFKA_ZOOKEEPER_CONNECT</span><span class="token punctuation">:</span> zookeeper<span class="token punctuation">:</span><span class="token number">2181</span></span>
<span class="line">      <span class="token key atrule">KAFKA_ADVERTISED_LISTENERS</span><span class="token punctuation">:</span> PLAINTEXT<span class="token punctuation">:</span>//localhost<span class="token punctuation">:</span><span class="token number">9092</span></span>
<span class="line">      <span class="token key atrule">KAFKA_OFFSETS_TOPIC_REPLICATION_FACTOR</span><span class="token punctuation">:</span> <span class="token number">1</span></span>
<span class="line">      <span class="token key atrule">KAFKA_AUTO_CREATE_TOPICS_ENABLE</span><span class="token punctuation">:</span> <span class="token string">'true'</span></span>
<span class="line">    <span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> kafka_data<span class="token punctuation">:</span>/var/lib/kafka/data</span>
<span class="line">    <span class="token key atrule">depends_on</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> zookeeper</span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line">  <span class="token key atrule">zookeeper</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> confluentinc/cp<span class="token punctuation">-</span>zookeeper<span class="token punctuation">:</span>7.4.0</span>
<span class="line">    <span class="token key atrule">container_name</span><span class="token punctuation">:</span> game<span class="token punctuation">-</span>zookeeper</span>
<span class="line">    <span class="token key atrule">environment</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">ZOOKEEPER_CLIENT_PORT</span><span class="token punctuation">:</span> <span class="token number">2181</span></span>
<span class="line">      <span class="token key atrule">ZOOKEEPER_TICK_TIME</span><span class="token punctuation">:</span> <span class="token number">2000</span></span>
<span class="line">    <span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> zookeeper_data<span class="token punctuation">:</span>/var/lib/zookeeper/data</span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line">  <span class="token comment"># Prometheus - 监控告警</span></span>
<span class="line">  <span class="token key atrule">prometheus</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> prom/prometheus<span class="token punctuation">:</span>v2.47.0</span>
<span class="line">    <span class="token key atrule">container_name</span><span class="token punctuation">:</span> game<span class="token punctuation">-</span>prometheus</span>
<span class="line">    <span class="token key atrule">ports</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"9090:9090"</span></span>
<span class="line">    <span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> ./prometheus/prometheus.yml<span class="token punctuation">:</span>/etc/prometheus/prometheus.yml</span>
<span class="line">      <span class="token punctuation">-</span> prometheus_data<span class="token punctuation">:</span>/prometheus</span>
<span class="line">    <span class="token key atrule">command</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">'--config.file=/etc/prometheus/prometheus.yml'</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">'--storage.tsdb.path=/prometheus'</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">'--web.console.libraries=/etc/prometheus/console_libraries'</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">'--web.console.templates=/etc/prometheus/consoles'</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">'--web.enable-lifecycle'</span></span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line">  <span class="token comment"># Grafana - 可视化面板</span></span>
<span class="line">  <span class="token key atrule">grafana</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> grafana/grafana<span class="token punctuation">:</span>10.1.0</span>
<span class="line">    <span class="token key atrule">container_name</span><span class="token punctuation">:</span> game<span class="token punctuation">-</span>grafana</span>
<span class="line">    <span class="token key atrule">ports</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">"3000:3000"</span></span>
<span class="line">    <span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> grafana_data<span class="token punctuation">:</span>/var/lib/grafana</span>
<span class="line">      <span class="token punctuation">-</span> ./grafana/dashboards<span class="token punctuation">:</span>/etc/grafana/provisioning/dashboards</span>
<span class="line">      <span class="token punctuation">-</span> ./grafana/datasources<span class="token punctuation">:</span>/etc/grafana/provisioning/datasources</span>
<span class="line">    <span class="token key atrule">environment</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> GF_SECURITY_ADMIN_PASSWORD=admin123</span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line"><span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">clickhouse_data</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">redis_data</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">kafka_data</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">zookeeper_data</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">prometheus_data</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">grafana_data</span><span class="token punctuation">:</span></span>
<span class="line"></span>
<span class="line"><span class="token key atrule">networks</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">default</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">name</span><span class="token punctuation">:</span> game<span class="token punctuation">-</span>telemetry</span>
<span class="line"></span></code></pre>
