iv><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="启动脚本" tabindex="-1"><a class="header-anchor" href="#启动脚本"><span>启动脚本</span></a></h3>
<div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre v-pre><code class="language-bash"><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># deploy-game-telemetry.sh</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">set</span> <span class="token parameter variable">-e</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">"🚀 开始部署游戏OpenTelemetry分析系统..."</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 1. 创建必要目录</span></span>
<span class="line"><span class="token function">mkdir</span> <span class="token parameter variable">-p</span> <span class="token punctuation">{</span>logs,prometheus,grafana/dashboards,grafana/datasources,clickhouse<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. 生成Prometheus配置</span></span>
<span class="line"><span class="token function">cat</span> <span class="token operator">></span> prometheus/prometheus.yml <span class="token operator">&lt;&lt;</span> <span class="token string">EOF</span>
<span class="line">global:</span>
<span class="line">  scrape_interval: 15s</span>
<span class="line"></span>
<span class="line">scrape_configs:</span>
<span class="line">  - job_name: 'otel-collector'</span>
<span class="line">    static_configs:</span>
<span class="line">      - targets: ['otel-collector:8889']</span>
<span class="line"></span>
<span class="line">  - job_name: 'game-servers'</span>
<span class="line">    static_configs:</span>
<span class="line">      - targets: ['game-server:8080']</span>
<span class="line">    metrics_path: '/metrics'</span>
<span class="line">EOF</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 3. 生成Grafana数据源配置</span></span>
<span class="line"><span class="token function">cat</span> <span class="token operator">></span> grafana/datasources/datasources.yml <span class="token operator">&lt;&lt;</span> <span class="token string">EOF</span>
<span class="line">apiVersion: 1</span>
<span class="line"></span>
<span class="line">datasources:</span>
<span class="line">  - name: ClickHouse</span>
<span class="line">    type: vertamedia-clickhouse-datasource</span>
<span class="line">    url: http://clickhouse:8123</span>
<span class="line">    database: game_analytics</span>
<span class="line">    basicAuth: true</span>
<span class="line">    basicAuthUser: analytics_user</span>
<span class="line">    basicAuthPassword: analytics_password</span>
<span class="line"></span>
<span class="line">  - name: Prometheus</span>
<span class="line">    type: prometheus</span>
<span class="line">    url: http://prometheus:9090</span>
<span class="line">    isDefault: true</span>
<span class="line"></span>
<span class="line">  - name: Redis</span>
<span class="line">    type: redis-datasource</span>
<span class="line">    url: redis://redis:6379</span>
<span class="line">EOF</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 4. 启动服务</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">"📦 启动OpenTelemetry服务栈..."</span></span>
<span class="line"><span class="token function">docker-compose</span> <span class="token parameter variable">-f</span> docker-compose-otel-game.yml up <span class="token parameter variable">-d</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 5. 等待服务启动</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">"⏳ 等待服务启动..."</span></span>
<span class="line"><span class="token function">sleep</span> <span class="token number">30</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 6. 初始化ClickHouse表结构</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">"🗄️ 初始化ClickHouse表结构..."</span></span>
<span class="line"><span class="token function">docker</span> <span class="token builtin class-name">exec</span> game-clickhouse clickhouse-client <span class="token parameter variable">--query</span> <span class="token string">"</span>
<span class="line">CREATE DATABASE IF NOT EXISTS game_analytics;</span>
<span class="line"></span>
<span class="line">USE game_analytics;</span>
<span class="line"></span>
<span class="line">-- OpenTelemetry Traces表</span>
<span class="line">CREATE TABLE IF NOT EXISTS otel_traces (</span>
<span class="line">    timestamp DateTime64,</span>
<span class="line">    trace_id String,</span>
<span class="line">    span_id String,</span>
<span class="line">    parent_span_id String,</span>
<span class="line">    span_name String,</span>
<span class="line">    span_kind String,</span>
<span class="line">    service_name String,</span>
<span class="line">    service_version String,</span>
<span class="line">    attributes Map(String, String),</span>
<span class="line">    events Array(String),</span>
<span class="line">    status_code String,</span>
<span class="line">    status_message String</span>
<span class="line">) ENGINE = MergeTree()</span>
<span class="line">PARTITION BY toYYYYMM(timestamp)</span>
<span class="line">ORDER BY (service_name, span_name, timestamp);</span>
<span class="line"></span>
<span class="line">-- OpenTelemetry Metrics表</span>
<span class="line">CREATE TABLE IF NOT EXISTS otel_metrics (</span>
<span class="line">    timestamp DateTime64,</span>
<span class="line">    metric_name String,</span>
<span class="line">    metric_type String,</span>
<span class="line">    value Float64,</span>
<span class="line">    attributes Map(String, String),</span>
<span class="line">    resource_attributes Map(String, String)</span>
<span class="line">) ENGINE = MergeTree()</span>
<span class="line">PARTITION BY toYYYYMM(timestamp)</span>
<span class="line">ORDER BY (metric_name, timestamp);</span>
<span class="line"></span>
<span class="line">-- OpenTelemetry Logs表</span>
<span class="line">CREATE TABLE IF NOT EXISTS otel_logs (</span>
<span class="line">    timestamp DateTime64,</span>
<span class="line">    severity_text String,</span>
<span class="line">    severity_number UInt8,</span>
<span class="line">    body String,</span>
<span class="line">    attributes Map(String, String),</span>
<span class="line">    resource_attributes Map(String, String)</span>
<span class="line">) ENGINE = MergeTree()</span>
<span class="line">PARTITION BY toYYYYMM(timestamp)</span>
<span class="line">ORDER BY (severity_text, timestamp);</span>
<span class="line">"</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">"✅ 游戏OpenTelemetry分析系统部署完成！"</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">"📊 访问地址:"</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">"  - Grafana: http://localhost:3000 (admin/admin123)"</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">"  - Prometheus: http://localhost:9090"</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">"  - ClickHouse: http://localhost:8123"</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">"  - OTLP HTTP: http://localhost:4318"</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">"  - OTLP gRPC: localhost:4317"</span></span>
<span class="line"></span></code></pre>
